draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw leaf
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 - 40, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw body
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2 - 30 + Math.cos(t) * 10, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2 + 30 + Math.cos(t) * 10, H/2 + 150);
  ctx.stroke();

  // draw legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140);
  ctx.lineTo(W/2 - 20, H/2 + 170);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140);
  ctx.lineTo(W/2 + 20, H/2 + 170);
  ctx.stroke();

  ctx.restore();
}
